IMPORT connectors.sources-{{environment}} AS sources;

/* ========================================
   PART 1: Deduplication of Input Streams
   ======================================== */

/* Note that we annotate non-hidden tables as no_query so we don't create the default API endpoints.
   We explicitly create API access functions for those tables in the API section below.
 */

/* Create versioned state tables from CDC streams by taking the latest version. */
/*+no_query */
Actor := DISTINCT sources.ActorUpdateStream ON actor_id ORDER BY updated_at DESC;
/*+no_query */
Resource := DISTINCT sources.ResourceUpdateStream ON resource_id ORDER BY updated_at DESC;

/* Filters out invalid events */
_FilteredAuditEvent := SELECT * FROM sources.AuditEvent WHERE id<>'';
_AuditEvent := SELECT * FROM _FilteredAuditEvent;


/* ========================================
   PART 2: Event Enrichment
   ======================================== */

/* Enrich audit events with actor and resource information using temporal joins
   This captures the state of actors and resources at the time of the event and ensures that the join is consistent in time.
   We use a left join to identify missing actors/resources.
*/
_EnrichedAuditEventWithMissing := SELECT
    e.id,
    e.actor_id,
    e.resource_id,
    e.action,
    e.outcome,
    e.context,
    e.event_timestamp,
    e.source_timestamp,
    a.actor_type,
    a.actor_identifier,
    a.display_name AS actor_display_name,
    a.attribute AS actor_attribute,
    r.resource_type,
    r.resource_identifier,
    r.display_name AS resource_display_name,
    r.attribute AS resource_attribute
FROM _AuditEvent e
JOIN Actor FOR SYSTEM_TIME AS OF e.event_timestamp AS a
    ON e.actor_id = a.actor_id
JOIN Resource FOR SYSTEM_TIME AS OF e.event_timestamp AS r
    ON e.resource_id = r.resource_id;

_EnrichedAuditEvent := SELECT * FROM _EnrichedAuditEventWithMissing
    WHERE actor_identifier IS NOT NULL AND resource_identifier IS NOT NULL;

/* ========================================
   PART 3: Event Aggregation
   ======================================== */

/* Data cube of enriched audit events by key dimensions
   Uses hourly CUMULATE window that updates every minute */
_EventAggregationStream := SELECT
    COALESCE(action,'') AS action,
    COALESCE(outcome,'') AS outcome,
    COALESCE(actor_type,'') AS actor_type,
    COALESCE(resource_type,'') AS resource_type,
    window_start,
    window_end,
    window_time,
    COUNT(*) AS event_count,
    COUNT(DISTINCT actor_id) AS unique_actors,
    COUNT(DISTINCT resource_id) AS unique_resources
FROM TABLE(
    CUMULATE(
        TABLE _EnrichedAuditEvent,
        DESCRIPTOR(event_timestamp),
        INTERVAL '1' MINUTE,    -- step size (updates every minute)
        INTERVAL '1' HOUR       -- max window size (hourly window)
    )
)
GROUP BY window_start, window_end, window_time,
         CUBE (action, outcome, actor_type, resource_type);

-- Cumulate event streams need to be deduplicated to get the most recent per window.
-- We prefer CUMULATE over TUMBLE windows because they provide intermediate results (e.g. every minute)
-- but this requires careful handling downstream to avoid storing or processing the same time-window twice.

/** Query for hourly aggregates of audit events for event count, and number of unique actors/resources.
    Data cube of events by action, outcome, actor_type, and resource_type aggregated per hour (in decreasing order).
    Use empty string '' to query for a rollup by dimension.
 */
/*+query_by_any(action, outcome, actor_type, resource_type) */
EventAggregation := DISTINCT _EventAggregationStream
                 ON action, outcome, actor_type, resource_type, window_start
                 ORDER BY window_time DESC;

/* ========================================
   PART 4: Actor Aggregation
   ======================================== */

/* Hourly CUMULATE window aggregation by actor to analyze trends */
_ActorAggregationStream := SELECT
    actor_id,
    window_start,
    window_end,
    window_time,
    COUNT(*) AS event_count,
    COUNT(DISTINCT resource_id) AS unique_resources,
    SUM(CASE WHEN outcome = 'SUCCESS' THEN 1 ELSE 0 END) AS success_count,
    SUM(CASE WHEN outcome = 'FAILURE' THEN 1 ELSE 0 END) AS failure_count
FROM TABLE(
    CUMULATE(
        TABLE _EnrichedAuditEvent,
        DESCRIPTOR(event_timestamp),
        INTERVAL '1' MINUTE,
        INTERVAL '1' HOUR
    )
)
GROUP BY actor_id, window_start, window_end, window_time;

/** Query for hourly aggregates of events by action with event counts, unique resources impacted, and number of success/failure.
 */
/*+query_by_all(actor_id) */
ActorAggregation := DISTINCT _ActorAggregationStream ON actor_id, window_start ORDER BY window_time DESC;

/** Query for event aggregations across an actor session (determined by 5 minutes of inactivity) */
/*+query_by_all(actor_id) */
ActorSessions := SELECT
        actor_id,
        window_start,
        window_end,
        window_time,
        COUNT(*) AS event_count,
        COUNT(DISTINCT resource_id) AS unique_resources
FROM TABLE(SESSION(
        TABLE _EnrichedAuditEvent PARTITION BY actor_id,
        DESCRIPTOR(event_timestamp),
        INTERVAL '5' MINUTE
    )
)
GROUP BY actor_id, window_start, window_end, window_time
ORDER BY window_start DESC;


/* ========================================
   PART 5: Identify Events of Interest
   ======================================== */

/* Establish baseline table for event alerts with relationships to actors and resources */
/*+no_query*/
EnrichedAuditEventAlert := SELECT * FROM _EnrichedAuditEvent ORDER BY event_timestamp DESC;
EnrichedAuditEventAlert.actor := SELECT * FROM Actor a WHERE a.actor_id = this.actor_id;
EnrichedAuditEventAlert.resource := SELECT * FROM Resource r WHERE r.resource_id = this.resource_id;


/* Pushes an alert on DELETE actions with FAILURE outcome */
DeleteFailureAlert := SUBSCRIBE SELECT * FROM EnrichedAuditEventAlert
    WHERE action = 'DELETE' AND outcome = 'FAILURE';

/** Pushes an alert when an actor has more than 2 failures in a single hour window */
HighFailureRateAlert := SUBSCRIBE SELECT * FROM _ActorAggregationStream
    WHERE failure_count > 2;

/* Export alerts to logger */
EXPORT DeleteFailureAlert TO logger.DeleteFailure;
EXPORT HighFailureRateAlert TO logger.HighFailureRate;

/* ========================================
   API Interface
   ======================================== */


/** Returns delete failures during the given time period.
  from/to_time must be RFC-3339 compliant date time scalar. */
DeleteFailure(from_time TIMESTAMP NOT NULL, to_time TIMESTAMP NOT NULL) :=
    SELECT * FROM DeleteFailureAlert
    WHERE :from_time <= event_timestamp AND :to_time > event_timestamp
    ORDER BY event_timestamp DESC;

/** Returns instances when the failure rate per actor per hour exceeds the threshold.
  from/to_time must be RFC-3339 compliant date time scalar. */
HighFailureRate(from_time TIMESTAMP NOT NULL, to_time TIMESTAMP NOT NULL) :=
    SELECT * FROM HighFailureRateAlert
    WHERE :from_time <= window_end AND :to_time > window_start
    ORDER BY window_start DESC;


/* ========================================
   Event Archive
   ======================================== */


/*+partition_key(time_bucket), primary_key(time_bucket, id), no_query */
EnrichedAuditEventArchive := SELECT EXTRACT(YEAR FROM event_timestamp) * 1000 + EXTRACT(DOY FROM event_timestamp) as time_bucket,
                                    * FROM _EnrichedAuditEvent;

/** Returns all audit events in the given time period
    from/to_time must be RFC-3339 compliant date time scalar.
*/
/*+engine(iceberg) */
EnrichedAuditEvent(from_time TIMESTAMP NOT NULL, to_time TIMESTAMP NOT NULL) :=
SELECT * FROM EnrichedAuditEventArchive
WHERE :from_time <= event_timestamp AND :to_time > event_timestamp
ORDER BY event_timestamp DESC;

/* ========================================
   Monitoring to ensure job is working correctly
   ======================================== */

/* Capture all events that don't have matching actor or resource records in Iceberg */

_AuditEventsMissingDimensions := SELECT * FROM _EnrichedAuditEventWithMissing
                                WHERE actor_identifier IS NULL OR resource_identifier IS NULL;

/*+engine(iceberg) */
AuditEventsMissingDimensions(from_time TIMESTAMP NOT NULL) :=
SELECT * FROM _AuditEventsMissingDimensions
WHERE :from_time <= event_timestamp
ORDER BY event_timestamp DESC;

/* Aggregate hourly time-windows of events by context (i.e. where they originate) to identify anomalies
 */

_HourlyEventsByContext := SELECT
    COALESCE(context, '') AS context,
    window_start,
    window_end,
    window_time,
    COUNT(*) AS event_count,
    COUNT(DISTINCT action) AS distinct_actions,
    COUNT(DISTINCT resource_type) AS distinct_resource_types,
    COUNT(DISTINCT actor_type) AS distinct_actor_types
FROM TABLE(
    TUMBLE(
        TABLE _EnrichedAuditEventWithMissing,
        DESCRIPTOR(event_timestamp),
        INTERVAL '1' HOUR
    )
)
GROUP BY context, window_start, window_end, window_time;

/*+engine(iceberg), query_by_any(context) */
HourlyEventsByContext := SELECT * FROM _HourlyEventsByContext ORDER BY window_start DESC, context ASC;

/* ========================================
   TEST CASES
   ======================================== */

/*+test */
EnrichedAuditEventTest := SELECT action, outcome, actor_type, resource_type, COUNT(*) AS num
    FROM EnrichedAuditEventArchive
    GROUP BY action, outcome, actor_type, resource_type
    ORDER BY action ASC, outcome ASC, actor_type ASC, resource_type ASC;

/*+test */
EventAggregationTest := SELECT action, outcome, actor_type, resource_type, window_time, event_count
    FROM EventAggregation
    ORDER BY window_time DESC, action ASC, outcome ASC, actor_type DESC, resource_type DESC;

/*+test */
ActorAggregationTest := SELECT actor_id, window_time, event_count, success_count, failure_count
    FROM ActorAggregation
    ORDER BY actor_id ASC, window_time DESC;

/*+test */
DeleteFailureAlertTest := SELECT COUNT(*) AS alert_count FROM DeleteFailureAlert;

/*+test */
HighFailureRateAlertTest := SELECT actor_id, failure_count FROM HighFailureRateAlert
    ORDER BY actor_id ASC;

/*+test */
HourlyEventsByContextTest := SELECT * FROM HourlyEventsByContext;

